$ErrorActionPreference = "Stop"
if (-not (Test-Path "backend\src\jobs")) { Write-Host "Ejecuta este script desde la raiz del repo (carpeta Contratos)." -ForegroundColor Red; exit 1 }
$b = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "backend\src\utils\reporteMensualArrendamientos.js"), [Convert]::FromBase64String($b))
Write-Host "OK backend\src\utils\reporteMensualArrendamientos.js"
$b = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "backend\src\routes\arrendamientos\dashboard.js"), [Convert]::FromBase64String($b))
Write-Host "OK backend\src\routes\arrendamientos\dashboard.js"
$b = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "frontend\src\pages\arrendamientos\DashboardArrendamientos.jsx"), [Convert]::FromBase64String($b))
Write-Host "OK frontend\src\pages\arrendamientos\DashboardArrendamientos.jsx"
Write-Host "Listo. Ahora: git add -A; git commit -m Semaforo de vencimientos 90/180 en dashboard y reporte; git push" -ForegroundColor Green